#[wasm_bindgen]
pub fn calculate_course_recommendation(user_data: &[f32]) -> Vec<u32> {
  let mut scores = vec![];

  // Complex ML algorithm
  for i in 0..user_data.len() {
    let score = user_data[i] * 100.0 + (i as f32).sqrt();
    scores.push(score as u32);
  }

  // Sort by score
  scores.sort_by(|a, b| b.cmp(a));
  scores
}

