// Send metrics to analytics
function sendToAnalytics(metric) {
  if (navigator.sendBeacon) {
    const body = JSON.stringify(metric);
    navigator.sendBeacon('/api/metrics', body);
  } else {
    fetch('/api/metrics', {
      method: 'POST',
      body: JSON.stringify(metric),
      keepalive: true
    });
  }
}

// Monitor all Core Web Vitals
getCLS(sendToAnalytics);  // Cumulative Layout Shift
getFID(sendToAnalytics);  // First Input Delay
getFCP(sendToAnalytics);  // First Contentful Paint
getLCP(sendToAnalytics);  // Largest Contentful Paint
getTTFB(sendToAnalytics); // Time to First Byte

// Or in React component
import { useEffect } from 'react';

export function PerformanceMonitor() {
  useEffect(() => {
    if ('PerformanceObserver' in window) {
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          console.log('Performance entry:', entry);
          sendToAnalytics(entry);
        }
      });

      observer.observe({ entryTypes: ['navigation', 'resource', 'paint'] });
    }
  }, []);

  return null;
}

name: Lighthouse Performance Check

on:
  pull_request:
    branches: [main]

jobs:
  lighthouse:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3

      - name: Build application
        run: npm run build

      - name: Run Lighthouse
        uses: treosh/lighthouse-ci-action@v9
        with:
          configPath: './lighthouserc.json'
          uploadArtifacts: true
          temporaryPublicStorage: true

      - name: Comment PR with results
        uses: actions/github-script@v6
        if: always()
        with:
          script: |
            const fs = require('fs');
            const results = JSON.parse(fs.readFileSync('./lhr.json'));
            const scores = results.categories;

            const comment = `
            ## Lighthouse Report
            - Performance: ${scores.performance.score * 100}
            - Accessibility: ${scores.accessibility.score * 100}
            - Best Practices: ${scores['best-practices'].score * 100}
            - SEO: ${scores.seo.score * 100}
            `;

            github.rest.issues.createComment({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body: comment
            });
